# Imports the HMI tag table and screens generated by build_hmi.py into the
# first HMI target of the project, compiles the HMI and saves (decisions/0007).
# Refuses while TIA Portal is open (single writer, AGENTS rule 6).
param(
    [string]$ProjectPath = ((Get-ChildItem (Join-Path $PSScriptRoot "..\tia") -Recurse -Filter "*.ap15_1" -ErrorAction SilentlyContinue | Select-Object -First 1).FullName),
    [string]$BuildDir    = (Join-Path $PSScriptRoot "..\build\hmi"),
    [string]$ApiDir      = "C:\Program Files\Siemens\Automation\Portal V15_1\PublicAPI\V15.1"
)
$ErrorActionPreference = 'Stop'
$ProjectPath = [System.IO.Path]::GetFullPath($ProjectPath)
$BuildDir    = [System.IO.Path]::GetFullPath($BuildDir)
if (Get-Process -Name 'Siemens.Automation.Portal' -ErrorAction SilentlyContinue) {
    throw "TIA Portal is open. Save and close it first (AGENTS rule 6)."
}
$engDll = Join-Path $ApiDir 'Siemens.Engineering.dll'
$hmiDll = Join-Path $ApiDir 'Siemens.Engineering.Hmi.dll'
[System.Reflection.Assembly]::LoadFrom($engDll) | Out-Null
[System.Reflection.Assembly]::LoadFrom($hmiDll) | Out-Null

$src = @'
using System;
using System.IO;
using System.Collections.Generic;
using Siemens.Engineering;
using Siemens.Engineering.HW;
using Siemens.Engineering.HW.Features;
using Siemens.Engineering.Compiler;
using Siemens.Engineering.Hmi;

public class HmiApply
{
    static void Walk(DeviceItem it, int depth, List<DeviceItem> all)
    {
        if (depth > 12) return;
        all.Add(it);
        foreach (DeviceItem s in it.DeviceItems) Walk(s, depth + 1, all);
    }

    static HmiTarget Find(Project prj)
    {
        foreach (Device d in prj.Devices)
        {
            var all = new List<DeviceItem>();
            foreach (DeviceItem it in d.DeviceItems) Walk(it, 0, all);
            foreach (DeviceItem it in all)
            {
                SoftwareContainer sc = null;
                try { sc = it.GetService<SoftwareContainer>(); } catch { }
                if (sc != null && sc.Software is HmiTarget) return (HmiTarget)sc.Software;
            }
        }
        return null;
    }

    public static int Run(string prjFile, string buildDir)
    {
        TiaPortal portal = new TiaPortal(TiaPortalMode.WithoutUserInterface);
        Project prj = null;
        int failed = 0;
        try
        {
            prj = portal.Projects.Open(new FileInfo(prjFile));
            HmiTarget hmi = Find(prj);
            if (hmi == null) throw new Exception("no HMI target in the project");
            Console.WriteLine("HMI target: " + hmi.Name);

            // A failed import disposes the whole project session: stop at the first
            // failure (nothing is saved) instead of reporting disposed-object noise.
            var files = new List<string>(Directory.GetFiles(buildDir, "Tags_*.xml"));
            files.AddRange(Directory.GetFiles(buildDir, "Screen_*.xml"));
            foreach (string f in files)
            {
                try
                {
                    if (Path.GetFileName(f).StartsWith("Tags_"))
                        hmi.TagFolder.TagTables.Import(new FileInfo(f), ImportOptions.Override);
                    else
                        hmi.ScreenFolder.Screens.Import(new FileInfo(f), ImportOptions.Override);
                    Console.WriteLine("OK   " + Path.GetFileName(f));
                }
                catch (Exception e)
                {
                    Console.WriteLine("FAIL " + Path.GetFileName(f) + " :: " + e.Message);
                    Console.WriteLine("NOT SAVED");
                    return 1;
                }
            }

            CompilerResult r = hmi.GetService<ICompilable>().Compile();
            Console.WriteLine("HMI compile: state=" + r.State + " errors=" + r.ErrorCount + " warnings=" + r.WarningCount);
            Print(r.Messages, "  ", 0);
            if (failed == 0 && r.ErrorCount == 0) { prj.Save(); Console.WriteLine("SAVED"); }
            else Console.WriteLine("NOT SAVED (import failures or compile errors)");
            return failed + r.ErrorCount;
        }
        finally
        {
            try { if (prj != null) prj.Close(); } catch { }
            try { portal.Dispose(); } catch { }
        }
    }

    static void Print(CompilerResultMessageComposition ms, string ind, int depth)
    {
        if (depth > 8) return;
        foreach (CompilerResultMessage m in ms)
        {
            if (m.State != CompilerResultState.Success && m.State != CompilerResultState.Information || depth < 1)
                Console.WriteLine(ind + m.State + ": " + m.Path + " " + m.Description);
            Print(m.Messages, ind + "  ", depth + 1);
        }
    }
}
'@

Add-Type -TypeDefinition $src -ReferencedAssemblies $engDll, $hmiDll, 'System.Core' -ErrorAction Stop
$rc = [HmiApply]::Run($ProjectPath, $BuildDir)
exit $rc
